  str_story_banner_131 = "<color=#FFB400>เดย์นา</color>นี่นา PlayerName นำเส้นทางโจมตีให้พวกเราที!",
  str_story_banner_132 = "ได้ผลด้วย ดาเมจการโจมตีของเดย์นาขยายไปสุดรอยแยกแล้ว\nถ้าเราทำซ้ำได้อีกสักสองสามครั้งนะ...",
  str_story_banner_133 = "PlayerName เห็น<color=#FFB400>จุดหลบหนี</color>ตรงนั้นไหม\nนั่นแหละคือทางออกของเรา",
  str_story_banner_134 = "แต่จุดหลบหนีจะยังคง<color=#FFB400>ล็อกอยู่</color>จนกว่า<color=#FFB400>ศัตรูทั้งหมดจะพ่ายแพ้</color>!\nให้ไวล่ะ!",
  str_story_banner_135 = "จุดหลบหนี<color=#FFB400>ปลดล็อกแล้ว</color>! PlayerName พาทุกคนออกไปตอนที่ยังมีโอกาส",
  str_story_banner_136 = "ถ้าเราไปถึงจุดหลบหนีได้ เราก็จะรอด",
  str_story_banner_137 = "คุณจำได้ไหม ออโรเรียนมีสกิลหลายแบบ และไม่ว่าสกิลไหนก็พลิกสถานการณ์การต่อสู้ได้",
  str_story_banner_186 = "โดยเฉพาะนำสกิลเหล่านี้มาใช้<color=#FFB400>ผสมกัน</color>!",
  str_story_banner_138 = "ยิ่งมีช่องสีน้ำเงินอยู่รอบตัว<color=#FFB400>ไวซ์</color>มากเท่าใด เอฟเฟกต์สกิลของเธอก็ยิ่งแข็งแกร่งขึ้นเท่านั้น\nนอกจากนี้<color=#FFB400>มิสบลังค์</color>ยังสามารถเปลี่ยนช่องรอบ ๆ ให้กลายเป็นสีฟ้าได้อีกด้วย...",
  str_story_banner_139 = "คุณเข้าใจที่ฉันพูดไหม มาใช้<color=#FFB400>ความสามารถในการเปลี่ยนสีช่องของมิสบลังค์กันเถอะ</color>!",
  str_story_banner_140 = "ทีนี้ก็<color=#FFB400>เปิดใช้สกิลใช้งานของไวซ์</color>และเพิ่มดาเมจให้สูงสุดไปเลย!",
  str_story_banner_141 = "เรามีโอกาสเพิ่มที่จะรีเฟรชสกิลของเรา คราวนี้อำนาจการสร้างกลยุทธ์ตามสถานการณ์ในสนามรบอยู่ในมือคุณแล้ว",
  str_story_banner_142 = "รู้สึกเหมือนมีคนนำทางให้อยู่นะ\nเวลาของการโจมตีและการเลือกเส้นทางฉลาดมากเลย",
  str_story_banner_143 = "คือถ้าฉันต้องตามไปด้วย...\nฉันไม่คิดว่าตัวเองจะช่วยอะไรได้มากนักหรอก...",
  str_story_banner_144 = "ให้เป็นหน้าที่ฉันเถอะ ในแง่หนึ่ง การนำทางก็เป็นความถนัดพิเศษของฉันด้วย",
  str_story_banner_145 = "อย่าตื่นตูมไปเลย ใช้เหตุผลคิดก่อนแล้วค่อยตัดสินใจ!",
  str_story_banner_146 = "กำลังลำบากใช่ไหม จำไว้ว่าเส้นทางการต่อสู้ที่ยาวไกลที่สุดไม่ใช่ตัวเลือกที่ถูกต้องเสมอไป!",
  str_story_banner_188 = "ตอนนี้คุณจำเป็นต้องใช้พลัง<color=#FFB400>ของโซยา</color>เพื่อต่อเส้นทาง<color=#FFB400>สีฟ้า</color>และใช้<color=#FFB400>ความสามารถในการรักษา</color>ของเธอ!",
  str_story_banner_147 = "ในการต่อสู้ การมีเพื่อนร่วมทีมที่มีความสามารถในการรักษาเป็นสิ่งสำคัญอย่างยิ่ง!",
  str_story_banner_148 = "ครั้งนี้<color=#FFB400>ศัตรูอยู่นอกระยะการโจมตีของเราหมด</color>เลยเหรอ เราจำเป็นต้องหาทางเข้าใกล้ให้ได้ก่อน...",
  str_story_banner_149 = "ออโรเรียนบางคน<color=#FFB400>สามารถเปลี่ยนสีช่องรอบตัวให้เป็นธาตุที่ต้องการได้เลย</color> จึงสามารถสร้างเส้นทางการต่อสู้ที่ดีที่สุด",
  str_story_banner_183 = "<color=#FFB400>มิสบลังค์</color>มีความสามารถนี้ใช่ไหม",
  str_story_banner_150 = "มาลองดูกัน แล้วคุณจะเข้าใจ!",
  str_story_banner_184 = "ขอโทษที ฉันไม่ค่อยชินที่จะต้องต่อสู้กับเคเลสไทต์หรอกนะ แต่จะดีมากเลยถ้าฉันช่วยได้",
  str_story_banner_151 = "อิลลูมินาขอขอบคุณสำหรับความช่วยเหลืออย่างมหาศาลของคุณ คุณผู้หญิงจากลูโมโพลิส",
  str_story_banner_185 = "<color=#FFB400>อิลลูมินา</color> <color=#FFB400>ลูโมโพลิส</color>...\nผ่านมาตั้งหลายปีแล้ว ชาวออโรเรียนยังคงยึดมั่นกับบ้านของพวกเขาอย่างเหนียวแน่น",
  str_story_banner_152 = "<color=#FFB400>เนเมซิส</color>กับบลังค์มีความสามารถคล้ายคลึงกัน แต่เนเมซิสสามารถ<color=#FFB400>สร้างดาเมจ</color>ขณะเปลี่ยนช่องสีให้เป็น<color=#FFB400>สีเหลือง</color>ได้!",
  str_story_banner_153 = "การใช้ความสามารถในการเปลี่ยนสีช่องของออโรเรียนอย่างยืดหยุ่นสามารถนำไปสู่ประสบการณ์การต่อสู้ที่มีประสิทธิภาพยิ่งขึ้นได้\nอย่าลืมเรียนรู้และใช้ประโยชน์จากกลยุทธ์นี้ให้ดีละ ผู้นำทาง!",
  str_story_banner_165 = "ทีนี้ เพื่อให้การโจมตีมีประสิทธิภาพมากยิ่งขึ้น ให้วาดเส้นทางที่เอื้อให้ออโรเรียนจำนวนมากต่อสู้ด้วยกันได้",
  str_story_banner_154 = "ออโรเรียนสามารถโจมตีได้เฉพาะเวลาที่เดินไปตาม<color=#FFB400>เส้นทางที่สัมพันธ์กับธาตุของตัวเอง</color>เท่านั้น แต่กัปตันจะไม่อยู่ภายใต้ข้อจำกัดนี้",
  str_story_banner_250 = "<color=#FFB400>ออโรเรียนธาตุไฟจะโจมตีในช่องสีแดงเท่านั้น</color> <color=#FFB400>ออโรเรียนธาตุน้ำจะโจมตีในช่องสีฟ้าเท่านั้น</color> <color=#FFB400>ออโรเรียนธาตุไม้จะโจมตีในช่องสีเขียวเท่านั้น</color> ส่วน<color=#FFB400>ออโรเรียนธาตุสายฟ้าจะโจมตีในช่องสีเหลืองเท่านั้น</color>",
  str_story_banner_251 = "<color=#FFB400>เลือกสีที่เชื่อมต่อให้เหมาะกับการโจมตีของออโรเรียน</color>!",
  str_story_banner_155 = "ผู้นำทาง ยินดีต้อนรับสู่พื้นที่ท้าทาย คุณได้รับอนุญาตให้ใช้<color=#FFB400>เดย์นา</color>เท่านั้นในการท้าทายครั้งนี้",
  str_story_banner_156 = "คุณมีโอกาส<color=#FFB400>ต่อสู้ 5 รอบ</color>เท่านั้น เมื่อหมดรอบ การท้าทายของคุณจะล้มเหลว คุณต้องใช้ความสามารถ<color=#FFB400>ดาเมจพื้นที่</color>ของเดย์นาให้เกิดประโยชน์สูงสุด",
  str_story_banner_157 = "<color=#FFB400>สกิลใช้งาน</color>ของเดย์นาสามารถสร้างดาเมจพื้นที่ได้ด้วย ดังนั้นต้องใช้ให้เกิดประโยชน์",
  str_story_banner_158 = "เอาละผู้นำทาง ระวังมอนสเตอร์สร้างสมุนพวกนี้นะ อิคลิพไซท์ที่พวกมันเรียกมาอาจมีผลกระทบต่อคุณอย่างมาก",
  str_story_banner_159 = "ระวังตัวด้วย PlayerName! อิคลิพไซท์คราวนี้แตกต่างไปจากเดิมอยู่บ้าง!",
  str_story_banner_160 = "ตื่นตัวหน่อย PlayerName! ตัวนี้มีระยะโจมตีที่กว้างมาก!",
  str_story_banner_161 = "อย่าละเลยรายละเอียดเวลาออกคำสั่ง\nความอยู่รอดของทีมเราอยู่ในมือคุณแล้ว",
  str_story_banner_170 = "อิคลิพไซท์พวกนี้ไม่ค่อยปกติ มาสังเกตดูพวกมันอย่างใกล้ชิดก่อนดีกว่า",
  str_story_banner_171 = "นั่นหน่วยสอดแนมของศัตรู นี่พวกมันพยายามจะฉวยโอกาสช่วงชุลมุนรวบรวม<color=#FFB400>ข่าวกรอง</color>ของเรางั้นเหรอ เราต้องเอากลับคืนมาให้หมด!",
  str_story_banner_172 = "ลองระบุประเภทอิคลิพไซท์หน้าตาแบบนี้ดูสิ <color=#FFB400>ข่าวกรอง</color>อยู่กับพวกมันนี่ละ",
  str_story_banner_173 = "เมื่อได้ข้อมูลกลับมามากพอแล้ว เราก็จะ<color=#FFB400>ถอนกำลัง</color>โดยเร็วที่สุด\nเมืองใต้ดินต้านทานได้อีกไม่นานแล้ว!",
  str_story_banner_174 = "สังเกตอิคลิพไซท์ตัวเล็ก ๆ บินได้ที่อยู่ในระยะไกล!\nคู่มือการต่อสู้ระบุไว้ชัดเลยว่าพวกนี้ \"อันตราย\"",
  str_story_banner_175 = "อิคลิพไซท์ประเภทนี้เคลื่อนที่เร็วมาก ต้องจัดการอย่างระมัดระวัง!",
  str_story_banner_727 = "อู้หู! นี่คือเส้นแสงเหรอเนี่ย\nเป็นสถานที่ต่อสู้ของเราสินะ",
  str_story_banner_728 = "ว้าว! คุณนี่ทำได้สมชื่อชาวเคเลสไทต์จริง ๆ เลย\nมาอวดทักษะการออกคำสั่งของคุณให้ฉันดูหน่อยเป็นไง",
  str_story_banner_176 = "เห็นจุดที่เรืองแสงในสนามรบไหมหนูน้อย นั่นคือ<color=#FFB400>คริสตัลอุกกาบาต</color>!",
  str_story_banner_177 = "มันสามารถปล่อยพลังงานแสงเข้มข้นออกมา<color=#FFB400>เพื่อโจมตีศัตรูที่มี HP มากที่สุดโดยอัตโนมัติ</color>ได้ เพียงแค่คุณเดินเข้าไปหามัน ส่วนที่เหลือคงไม่ต้องให้ฉันบอกแล้วละ",
  str_story_banner_178 = "ยังมีคริสตัลอีก 2 ชิ้น มาดูซิว่าเราสามารถกำจัด<color=#FFB400>อิคลิปไซต์ขนาดใหญ่</color>ในระยะไกลนั่นได้ไหม\nไปเร็ว ไปเร็ว!",
  str_story_banner_179 = "แย่แล้ว! นั่นมันศัตรูที่เป็นภัยร้ายแรงนี่นา ผู้นำทาง ถอยไป! ค-คู่มือของฉันอยู่น-ไหนเนี่ย\nขอหารายละเอียดก่อน...",
  str_story_banner_180 = "มันคือ<color=#FFB400>เครื่องมือการป้องกันที่ทำงานไม่ปกติ</color>! อะไร ๆ ก็เริ่มโกลาหลมากขึ้นแล้วตอนนี้ ดังนั้นอย่าลืมตั้งสมาธิให้ดี!",
  str_story_banner_181 = "เราอาจพบกับดักที่ซับซ้อนอีกมากในอนาคต ดังนั้นใช้อันนี้เป็นเครื่องมือฝึกหัดเลยแล้วกัน",
  str_story_banner_192 = "PlayerName คุณได้ฝึกฝนเทคนิคการต่อสู้มาแล้วมากมาย และตอนนี้ฉันก็จะแนะนำให้คุณรู้จักอีกเทคนิคใหม่...",
  str_story_banner_193 = "คุณรู้อยู่แล้วว่าความสามารถของออโรเรียนและความยาวของเส้นทางนั้นสัมพันธ์กัน <color=#FFB400>ถ้าเส้นทางมีความยาวถึงที่กำหนด</color> ออโรเรียนจะสามารถเข้าสู่<color=#FFB400>ออโรราไทม์</color>ได้",
  str_story_banner_194 = "ออโรราไทม์คือความลับโบราณที่แม้แต่ชาวออโรเรียนเองก็ยังไม่เข้าใจแน่ชัด บางทีวันหนึ่งเราอาจสามารถเผยความจริงเรื่องความลับของฟากฟ้าก็ได้นะ...",
  str_story_banner_195 = "เอาละ ทีนี้ก็มาสร้างออโรราไทม์กัน!",
  str_story_banner_196 = "ทำไฮเปอร์คอนเนกชั่นให้สำเร็จเพื่อเข้าสู่ออโรราไทม์ ออโรเรียน<color=#FFB400>จะได้รับโอกาสให้ลงมือได้อีกครั้ง</color>",
  str_story_banner_197 = "ถ้าใช้อย่างชาญฉลาด คุณจะได้รับประโยชน์อย่างมาก...",
  str_story_banner_198 = "น-ผู้นำทาง นี่คือออโรราเหรอ เหมือนโลกหยุดหมุนไปเลย นี่คือโอกาสที่เหมาะสมที่สุดที่จะกำจัดศัตรูพวกนี้ให้หมดไปซะที!",
  str_story_banner_199 = "นี่คือด่านพิเศษ มันอาจช่วยพัฒนาเทคนิคการต่อสู้บางอย่างก็ได้นะ",
  str_story_banner_201 = "เอาละ ใช้ประโยชน์จากคอมโบต่อเนื่องของไวซ์ให้เต็มที่เพื่อกำจัดอิคลิพไซท์กัน!",
  str_story_banner_202 = "ตอนนี้พื้นที่เหวลึกแบ่งแยกเรากับศัตรูออกจากกัน เราจำเป็นต้องคิดหามาตรการตอบโต้...",
  str_story_banner_203 = "ที่ไวซ์พูดนั้นถูกต้อง คุณเห็นช่องสีฟ้าของสนามรบไหม รีบลงมือกันเถอะ!",
  str_story_banner_207 = "ดำเนินการต่อเพื่อออกอย่างรวดเร็ว",
  str_story_banner_210 = "หืม เส้นแสงนี้น่าสนใจนะ อาจได้เวลาที่คุณจะฝึกฝนกุญแจสำคัญต่อไปเพื่อการต่อสู้แล้วก็ได้",
  str_story_banner_211 = "คุณเห็นรูปแบบของ<color=#FFB400>ช่องสีแดง</color>นั่นไหม",
  str_story_banner_212 = "ความสามารถของออโรเรียนนั้นสัมพันธ์กับความยาวของเส้นทาง ถ้า<color=#FFB400>สามารถต่อเส้นทางให้ได้ความยาวที่กำหนดแล้ว</color> ออโรเรียนจะเข้าสู่<color=#FFB400>ออโรราไทม์</color>",
  str_story_banner_213 = "ออโรราไทม์คือความลับโบราณ... บางทีมันอาจเหมือนกับรัตติกาลสีขาวก็ได้...\nที่เป็นปริศนารอให้เราไขอยู่",
  str_story_banner_214 = "เอาละ ทีนี้ก็มาสร้างออโรราไทม์กัน!",
  str_story_banner_215 = "สถานการณ์เริ่มซับซ้อนแล้ว... ตั้งใจหน่อย เคเลสไทต์\nมาดูกันซิว่าคุณมีดียังไง",
  str_story_banner_216 = "ระวังอาวุธต่อสู้พิเศษพวกนั้นด้วยนะ พวกนี้จะ<color=#FFB400>โจมตี\nเป้าหมายแรกที่อยู่ด้านหน้าในแนวเส้นตรง</color> และมันจะเจ็บปวดมหาศาลเลย!",
  str_story_banner_217 = "กลุ่ม \"มืออาชีพ\" ของเราพร้อมแล้วที่จะจัดการเจ้าพวกนี้ ดังนั้นคุณก็เพียงแค่<color=#FFB400>อดทนต่อไปอีก 7 รอบ</color>เพื่อคว้าชัยชนะ คุณสามารถตรวจสอบความคืบหน้าได้ที่นี่",
  str_story_banner_218 = "ไปกันเลย! ทำให้พวกนี้เห็นเลยว่าการจะจัดการพวกเราได้ มันไม่ง่ายขนาดนั้น!",
  str_story_banner_219 = "ผู้นำทาง... เหตุด่วน เราต้องปกป้องอีฟ",
  str_story_banner_220 = "อีฟเปราะบางต่อการโจมตีของศัตรู ดังนั้นเราจำเป็นต้องเร็วกว่าศัตรูนั่น!",
  str_story_banner_221 = "ผู้นำทาง ครั้งนี้เราต้องพึ่งคุณแล้วละ ฉันเชื่อมั่นในตัวคุณนะ",
  str_story_banner_222 = "ผู้นำทาง <color=#FFB400>เครื่องจัดเก็บ</color>กำลังถูกอิคลิพไซท์รุมโจมตี!\nเรา<color=#FFB400>ต้องปกป้องอุปกรณ์นั่น</color>",
