  str_story_banner_228 = "อ๊ากกกก ไม่จบไม่สิ้นเลย! อย่าลืมใช้<color=#FFB400>โล่พลังงาน</color>ของเครื่องจัดเก็บเมื่อจวนตัว มันสามารถทนต่อดาเมจได้ <color=#FFB400>3 ครั้ง</color>!",
