  str_story_banner_238 = "\"<color=#FFB400>การต้านการโจมตีกายภาพ</color>\" ช่วยลด<color=#FFB400>ดาเมจกายภาพ</color>ลงอย่างมาก! ดูเหมือนว่าต้องใช้<color=#FFB400>คอมโบต่อเนื่อง</color>กับ<color=#FFB400>สกิลใช้งาน</color>ถึงจะสร้างดาเมจที่น่าพอใจได้",
  str_story_banner_239 = "อิคลิพไซท์ตัวนี้มีรูปร่างเตะตามาก... ถ้าฉันจำไม่ผิด มันสามารถร่าย<color=#FFB400>สายฟ้าทรงพลัง</color>ได้!",
  str_story_banner_240 = "<color=#FFB400>แตะที่อิคลิพไซท์</color>เพื่อดูตำแหน่งที่ชัดเจนของเป้าหมาย นำทางเราไปสู่ชัยชนะอย่างเช่นเคย!",
  str_story_banner_241 = "ฉันเชื่อว่านี่คือครั้งแรกที่เราพบอิคลิพไซท์ประเภทนี้\nขอเวลาฉันตรวจสอบบันทึกสักครู่ อันนี้จะยากนิด...",
  str_story_banner_242 = "เจอแล้ว! อิคลิพไซท์ประเภทนี้<color=#FFB400>สามารถให้บัฟกับเพื่อนที่อยู่รอบตัวได้</color> เราควรจัดการมันก่อนไหม...?",
  str_story_banner_243 = "ทำอะไรก็ได้อย่างนั้นใช่ไหม จำอิคลิพไซท์ที่ต้านทานการโจมตีธรรมดามาก ๆ ได้ไหมล่ะ\nตัวนี้ตรงข้ามเลย มันมี<color=#FFB400>พลังต้านสกิล</color>ด้วย!",
  str_story_banner_244 = "<color=#FFB400>คอมโบต่อเนื่อง</color>และ<color=#FFB400>สกิลใช้งาน</color>สร้างดาเมจ<color=#FFB400>น้อยลงอย่างมาก</color> พูดอีกนัยหนึ่งก็คือ โจมตีได้ทีละครั้งจนกว่าจะตาย!",
  str_story_banner_245 = "อะไรกัน ทำไมอิคลิพไซท์ประเภทนี้ถึงมาที่นี่ได้ล่ะ ถอยไป ผู้นำทาง!",
  str_story_banner_246 = "ตัวนี้จะ<color=#FFB400>ทำลายตัวเอง</color>เมื่อ HP ของมันลดต่ำกว่าที่กำหนด สร้างดาเมจมหาศาลให้กับพื้นที่รอบตัว!\nลองใช้การโจมตีระยะไกลดูสิ",
  str_story_banner_247 = "เข้ามาเลย ต้องมีอะไรใหม่โผล่มาอีกแล้วแน่ ๆ ...",
