  str_story_banner_252 = "อย่าปล่อยอิคลิพไซท์พวกนี้ไป มาทำงานร่วมกันต่อเถอะ!",
  str_story_banner_253 = "สเปลล์ฮาวนด์มีโล่ 3 ชั้น ถ้าพยายามทำลายโล่ของพวกมันในครั้งเดียวอาจจะยากหน่อย...",
  str_story_banner_254 = "ให้ฉันเป็นกัปตันเลยดีกว่า\nแบบนี้การใช้<color=#FFB400>ธาตุน้ำ</color>จะทำให้ฉัน ไวซ์ แล้วก็มิสบลังค์โจมตีด้วยกันได้!",
  str_story_banner_255 = "PlayerName คุณสังเกตรึเปล่า ดาเมจที่ได้รับจากสเปลล์ฮาวนด์สองตัวนี้ไม่เหมือนกัน",
  str_story_banner_256 = "อิคลิพไซท์ก็มีธาตุเหมือนพวกเรานี่แหละ\nการโจมตีอิคลิพไซท์โดยใช้ธาตุที่เหมาะสมจะสร้างดาเมจได้มากกว่า",
  str_story_banner_257 = "น้ำชนะไฟ ไฟชนะไม้ ไม้ชนะสายฟ้า และสายฟ้าชนะน้ำ!",
  str_story_banner_258 = "PlayerName นำพวกเราปราบอิคลิพไซท์พวกนี้เลย!",
  str_story_banner_259 = "ถ้าคุณมอบหมายให้ไวซ์เป็นกัปตันในช่องสีเหลืองส่วนต่อไป เธอกับฉันก็จะสามารถโจมตีด้วยกันได้!",
  str_story_banner_301 = "อ่า ทหารลูโมพวกนี้ทำให้ฉันนึกถึงวันเก่า ๆ มากเลย",
  str_story_banner_302 = "<color=#FFB400>แตะ</color>เพื่อดู<color=#FFB400>ข้อมูลโดยละเอียด</color>ของพวกเขา",
  str_story_banner_303 = "โห ดูนี่สิ อะไรเนี่ย ลูโมโพลิสยังใช้<color=#FFB400>กับดัก</color>ตกยุคแบบนี้อยู่อีกเหรอ",
  str_story_banner_304 = "กลิ่้นอายความอันตราย... ฉันคุ้น ๆ ว่าเคยเห็นแสงสีเหลืองบนกับดักนี้ที่ไหนมาก่อนนะ...",
  str_story_banner_305 = "อ๋อ มันคือหน้าไม้อัมพาต! ไหนดูซิ... มันน่าจะมี<color=#FFB400>ปุ่มสั่งการ</color>อยู่แถวนี้นะ...",
  str_story_banner_306 = "เจอแล้ว! ฮิฮิ เราแค่ต้องไปต่ออย่างระมัดระวังเพราะ... เดี๋ยวนะ ดูเหมือนจะมีอะไรไม่ถูกต้องกับตำแหน่งของไอ้พวกเวรลูโมโพลิส... ถ้าเผื่อว่า...",
  str_story_banner_307 = "ได้ใช้อุปกรณ์ของไอ้พวกเวรนี่โจมตีพวกมันเอง มันเบิกบานใจสิ้นดีเลย! ตราบใดที่เราระมัดระวัง และ<color=#FFB400>หลีกเลี่ยงแนวการยิงของอุปกรณ์นี่</color>ก็จะไม่เป็นอะไร",
