  str_story_banner_309 = "บร็อค ฉันเคยได้ยินมาก่อน ดูเหมือนว่ามันสามารถสร้างแฟนท่อมขึ้นมาเพื่อ<color=#FFB400>หลบเลี่ยงการโจมตี</color>ได้!",
  str_story_banner_310 = "แต่แฟนท่อมพวกนี้<color=#FFB400>ไม่สามารถต้านทานกับดักอัมพาตได้</color>!\nจัดการพวกมันด้วยกับดักนี้กันดีกว่า!",
  str_story_banner_311 = "...อะไรฟะ! เมื่อกี้ยังอยู่ตรงนี้อยู่เลย ท่าทางเราต้องใช้กับดักจริง ๆ ซะแล้ว!",
  str_story_banner_312 = "ใช่แล้ว บร็อค ไอ้พวกเวรนี่จัดการยากน่าดูเลย <color=#FFB400>โปรดใช้กับดักเพิ่มอีก</color>",
  str_story_banner_313 = "เราใช้กับดักอัมพาตโจมตีไอ้พวกเวรที่ไล่จับยากพวกนี้ได้เลยใช่ไหม\nฉันว่าฉันเข้าใจแล้วละ",
  str_story_banner_314 = "อุปกรณ์พิลึกอะไรอีกล่ะคราวนี้",
