  str_story_banner_316 = "ระวัง! เจ้านี่มันเคลื่อนที่ได้ อย่าให้ถูกจับส่งไปหาศัตรู!",
  str_story_banner_317 = "หา...? อิคลิพไซท์ตัวนี้... น่ารักดีงั้นเหรอ",
  str_story_banner_318 = "ไม่นะไม่ อย่าไปหลงรูปลักษณ์ของพวกมัน!\nถ้ามันเป็นอิคลิพไซท์ มันคือศัตรูของเรา!",
  str_story_banner_712 = "... ไวซ์พูดถูก อิคลิพไซท์ประเภทนั้นสามารถ<color=#FFB400>รักษาเพื่อนของตัวเองได้</color> ดังนั้นเราควรจัดการพวกมันเป็นอันดับแรก",
  str_story_banner_319 = "มอนสเตอร์ตัวใหญ่นี่ดูอันตรายมากเลย...\nPlayerName ระวังด้วยนะ!",
  str_story_banner_320 = "อิคลิพไซท์ขนปุกปุยนี่มันอะไรกัน\nฉันว่าไม่มีในคู่มือการต่อสู้นะ...",
  str_story_banner_321 = "นี่จะใช้รูปลักษณ์มาหลอกฉันอีกแล้วเหรอ ผู้นำทาง ช่วยถอยไปก่อน!\nเรื่องต่อสู้ให้พวกเราจัดการเอง!",
  str_story_banner_322 = "PlayerName คุณเห็น<color=#FFB400>มิติหมุนวน</color>ที่พื้นไหม",
  str_story_banner_323 = "ดูเหมือนว่า...<color=#FFB400>เราสามารถเดินทางไปมาได้อย่างรวดเร็วระหว่างมิติหมุนวนทั้งสอง</color>! น่าทึ่งมากเลย",
  str_story_banner_324 = "นี่อิคลิพไซท์แบบใหม่อีกแล้วเหรอ ฉันอ่านคู่มือการต่อสู้จะจบเล่มแล้วนะ...",
  str_story_banner_325 = "PlayerName กระทืบ<color=#FFB400>ช่องรูน</color>พวกนี้เลย ไม่งั้นมันจะเรียก<color=#FFB400>อิคลิพไซท์ตัวอื่น ๆ มาเพิ่ม!</color>",
  str_story_banner_326 = "<color=#FFB400>ไซฟอร์บ</color>นี่นา!\nมอนสเตอร์พวกนี้<color=#FFB400>สามารถดูดซับพลังจากช่องรอบ ๆ ที่มีธาตุเดียวกันเพื่อเพิ่มดาเมจของพวกมันได้</color>!",
