  str_story_banner_329 = "นั่นแหละ ทุกครั้งที่ HP <color=#FFB400>ของโกลด์เดอร์มืด</color>ลดลงต่ำกว่าที่กำหนด มันจะเข้าสู่สถานะ<color=#FFB400>ต้านทานดาเมจ</color>ในรอบนี้ ดื้อจริง ๆ เลย...",
