  str_story_banner_508 = "อ๋อ นั้นคือ<color=#FFB400>รางวัลเควสต์</color>อะไรสักอย่างหนึ่งสินะ?\nแปลว่าทุกครั้งที่เคลียร์ด่านได้ เราจะได้รับผลประโยชน์แบบนี้เหรอ",
