  str_story_banner_514 = "อะแฮ่ม ท่าทางคนที่มีคุณสมบัติเป็นสหายจะอยากเข้าร่วมด้วย",
  str_story_banner_515 = "ความแข็งแกร่งของเดย์นานี่สุดยอดไปเลย และเธอก็ชนะการประลองใต้ดินที่อัมบราตันมาแล้วมากมาย\nแต่เธอเองก็เข้าถึงยากมากเช่นกัน...",
