  str_story_banner_522 = "PlayerName เราเพิ่งได้รับข่าวสารจากทางเหนือ\nดูเหมือนว่าจะมีประสบการณ์ใหม่ ๆ ปรากฏขึ้น!",
  str_story_banner_523 = "ท่าทางจะมีประสบการณ์หลายประเภทที่สามารถให้ทรัพยากรเพื่อการเติบโตของออโรเรียนได้\nเมื่อมีเวลาก็ลองดูรายละเอียดได้นะ",
  str_story_banner_524 = "อ๋อใช่ และตารางเวลาใหม่ก็เริ่มใช้งานแล้ว จะดีที่สุดเลยถ้าคุณยืนยันโดยเร็ว\nพาไวซ์ไปดูสิ PlayerName",
  str_story_banner_260 = "เควสต์พวกนี้<color=#FFB400>รีเฟรชทุกวัน</color> มันอาจช่วยให้เราสะสมทรัพยากรที่จำเป็นได้",
  str_story_banner_525 = "รับรางวัลเด็ดอย่างเช่นลูมแอมเบอร์โดยการสะสมคะแนนกิจกรรม",
  str_story_banner_705 = "พวกนี้สามารถครอบคลุมค่าใช้จ่ายรายวันสำหรับโคลอสซัสได้ในอนาคต... นอกจากนี้ ต่อไปเรายังต้องเริ่มเรียนรู้วิธีบริหารจัดการโคลอสซัสด้วย...",
  str_story_banner_706 = "ดูเหมือนว่าเธอจะตั้งตัวเป็นรองผู้บัญชาการของคุณแล้วนะ",
  str_story_banner_526 = "ผู้นำทาง ระวังด้านหน้า!",
