  str_story_banner_528 = "คุณอาจพบกับการต่อสู้พิเศษ ๆ ในเส้นทางที่แยกออกไป เมื่อมีเวลาก็ลองดูได้นะ!",
  str_story_banner_529 = "เดี๋ยวก่อน ถึงแม้ว่าเมื่อแตะที่คำแนะนำเควสต์แล้ว คุณจะตรงไปที่จุดหมายได้เลย\nแต่ฉันพบอีกที่หนึ่งที่สามารถพาเราไปที่นั่นได้ ตามฉันมา!",
  str_story_banner_530 = "ที่หน้าจอหลัก แตะ<color=#FFB400>เควสต์</color>เพื่อตรงไปที่จุดหมายการผจญภัยของคุณ\nคุณยังไม่รู้ใช่ไหมล่ะ ฉันเพิ่งเจอวิธีน่ะ",
