  str_story_banner_534 = "คุณสามารถเลื่อนขั้นออโรเรียนหลังจากสะสมวัตถุดิบที่ต้องใช้สำหรับ<color=#FFB400>เลื่อนขั้นออโรเรียน</color> และอัปเกรดให้ถึงเลเวลสูงสุดปัจจุบัน",
  str_story_banner_535 = "ผู้นำทาง คุณเพิ่งเก็บวัตถุดิบล้ำค่าได้ ซึ่งก็คือ<color=#FFB400>ฮาร์ทสโตน</color>นั่นเอง\nตอนนี้เราสามารถสร้าง<color=#FFB400>พัฒนาการออโรเรียน</color>ได้แล้ว ตามฉันมาเลย!",
  str_story_banner_536 = "เมื่อสร้างพัฒนาการออโรเรียนสำเร็จจะ<color=#FFB400>เพิ่มค่าสถานะของออโรเรียน</color>และเสริมพลัง<color=#FFB400>สกิลต่าง ๆ</color>\nมาลองดูกันเลย!",
  str_story_banner_537 = "โคลอสซัสสว่างขึ้นทั้งลำเลย นี่แปลว่าเราสามารถทำการซ่อมแซมระบบง่าย ๆ ได้แล้วใช่ไหม",
