  str_story_banner_708 = "พื้นที่ที่ปิดอยู่แต่เดิม สามารถปลดล็อกได้แล้วในเวลานี้\nในที่สุดเราก็สามารถนำห้องหับที่ปิดไว้เฉย ๆ ถึง 17 ปีมาใช้ประโยชน์ได้แล้ว!",
  str_story_banner_538 = "ฉันเกือบลืมไปเลย ให้<color=#FFB400>มิสบลังค์</color>ที่เพิ่งผ่านการสรรหาเข้ามาใหม่ ๆ มาเข้าร่วมทีมของเราด้วยเถอะ",
