  str_story_banner_5020303 = "กำจัดสิ่งกีดขวางแล้ว! จัดการทีเดียวให้สิ้นซากไปเลย!",
  str_story_banner_5020311 = "คาดการณ์ผิดจริง ๆ! ฉันโดนกลยุทธ์หมาหมู่ของพวกอิคลิพไซท์ทำร้ายเข้าแล้ว",
  str_story_banner_5020312 = "จะติดอยู่ในสงครามพร่ากำลังกับอิคลิพไซท์พวกนี้ไม่ได้ ต้องรีบรักษาบาดแผลและออกไปให้เร็วที่สุด",
  str_story_banner_5020313 = "ยังปล่อย \"เพลิงลุกไหม้\" ได้อีกนะ รับผ้าพันแผลแล้วรีบไปรวมตัวกับคนอื่นเถอะ",
  str_story_banner_5020314 = "ดีมาก เมื่อเธอได้รับผ้าพันแผลที่เหลือด้วยการใช้เพลิงลุกไหม้แล้ว ก็น่าจะแข็งแรงพอที่จะเอาชนะศัตรูทั้งหมดได้ เข้ามาเลย เจ้าพวกอิคลิพไซท์!",
  str_story_banner_5020321 = "ท-ที่นี่ที่ไหนอะ?",
  str_story_banner_5020322 = "ระวังด้วย เราน่าจะถูกลากเข้ามาในเขตที่มีการสร้างอาวุธอารยธรรมโบราณ",
  str_story_banner_5020323 = "นี่เป็นช่วงของ \"การประลอง\" ที่มันพูดถึงรึเปล่า?",
  str_story_banner_5020324 = "น่าจะใช่ เตรียมตัวให้พร้อมเถอะ!",
  str_story_banner_5020325 = "ไปกันเลย นี่คือศึกสุดท้ายแล้ว!",
  str_story_banner_5020326 = "ฉันสัญญากับเอลวิสว่าจะช่วยให้เขาสมปรารถนา และทำให้ศิลาลมค้าเริ่มต้นทำงานอีกครั้ง",
  str_story_banner_5020327 = "ไอ้พวกสัตว์ประหลาด! อย่าเข้ามาใกล้นะ!",
  str_story_banner_5020328 = "เอลวิส นายเป็นยังไงบ้าง?",
  str_story_banner_50213211 = "ถึงจะบอกว่าทุกอย่างที่ทำไปก็เพื่อสัตว์มหัศจรรย์ แต่ไม่คิดว่ามันลำบากไปหน่อยเหรอ? แกคิดว่าไง ไคโล?",
  str_story_banner_50213212 = "โล...",
  str_story_banner_50213213 = "ใช่แล้ว! แต่ครั้งนี้ฉันต้องทำให้สำเร็จเพื่อให้อาจารย์ประทับใจ!",
  str_story_banner_50213214 = "โล?",
  str_story_banner_50213215 = "โห! จู่ ๆ อิคลิพไซท์ก็มากันเป็นฝูงเลย!",
  str_story_banner_50213216 = "โอ้ ไคโลหิวแล้วสินะ รีบจัดการพวกมันแล้วกลับไปฉลองกันดีกว่า!",
  str_story_banner_50213217 = "โล?",
  str_story_banner_50213218 = "เอ๋? ทำไมตราออกล่าไปอยู่ตรงนั้นล่ะ? แปลกจัง หรือว่าทำหล่นไปตอนที่เล่นกับโซรอซ? อืม ดีเหมือนกัน ไปกันเถอะ ไคโล!",
  str_story_banner_50213219 = "ป่วนได้ที่เลยนะ ไคโล!",
  str_story_banner_50213220 = "โล! โล!",
  str_story_banner_50213221 = "ฉีดน้ำจนชุ่มฉ่ำไปทั่ว... แต่ก็ยังมีอิคลิพไซท์เหลืออีกเยอะเลย วางตราออกล่าอีกหน่อยเถอะ!",
  str_story_banner_50213222 = "จู่ ๆ ก็มีความคิดสนุก ๆ ขึ้นมา! ไคโล พวกเราลุย!",
  str_story_banner_50213311 = "ร้อนจังเลยนะ! อยากเย็นสดชื่นหน่อยมั้ยล่ะ?",
  str_story_banner_50213312 = "เห็นอิคลิพไซท์ตรงนั้นรึเปล่า? พวกมันยืนอยู่บนตราสายน้ำของฉัน ฉันจะกระตุ้นตรานั่นให้เกิดน้ำพุที่แสนสดชื่น!",
  str_story_banner_50213313 = "อิคลิพไซท์โดนดีดขึ้นไปในอากาศ! ลั้นลา!",
  str_story_banner_50213314 = "ดูสิ! ตราใหม่จะเกิดขึ้นบนช่องที่ตราสายน้ำ 3 ตราครอบคลุมไปถึง",
  str_story_banner_50213315 = "เยี่ยมมาก! มาปราบศัตรูด้วยปืนฉีดน้ำของฉันกันเถอะ!",
  str_story_banner_50213401 = "อิคลิพไซท์จำนวนมากปรากฏในโรงละครนิรนามระหว่างการแสดงที่ยอดเยี่ยม! ไม่มีใครบอกได้ว่านี่เป็นภาพลวงตาที่เกิดจากการสูญเสียสติหรือภัยคุกคามที่แท้จริง แต่ดูเหมือนเจโน่จะไม่ได้รับผลกระทบใด ๆ บนเวที",
  str_story_banner_50213402 = "ยินดีต้อนรับแขกผู้มีเกียรติของเรา คุณ PlayerName มาใช้ไพ่แห่งต้นกำเนิดกับผมบนเวที!",
  str_story_banner_50213403 = "นอกจากนี้ ยังมีแขกรับเชิญอีกหนึ่งท่าน คุณพาโลม่า!",
  str_story_banner_50213404 = "ผู้ชมของเรามีมากจริง ๆ ทั้งออโรเรียนและอิคลิพไซท์!",
