  str_story_banner_52630011 = "ฝูง Eclipsites ขึ้นเรือแล้ว อย่าตื่นตกใจ.",
  str_story_banner_52630012 = "ใช้ Chain Combos ให้มากที่สุดเพื่อจุดไฟ Serpent Flares ของฉัน",
  str_story_banner_52630013 = "หลังจากจุดเปลวไฟอสรพิษสามดวงแล้ว ฉันสามารถใช้สกิลเรียกใช้อันทรงพลังของฉันเพื่อปลดปล่อยความโกรธเกรี้ยวของท้องทะเลใส่พวกมัน!",
  str_story_banner_52630014 = "จุดไฟ Serpent Flare ทำคอมโบต่อ จากนั้นจุดไฟที่เหลือ! Serpent Flares สามารถส่องสว่างได้ง่ายขึ้นในช่วงเวลาออโรรา",
  str_story_banner_527200401 = "Little Navigator ถึงตาคุณแล้วที่จะสั่งฉัน—ฉันหมายถึง Bullock 8",
  str_story_banner_527200402 = "ที่รักของฉัน! อย่าทำลายเขา!",
  str_story_banner_527200403 = "เขามีเสน่ห์ดึงดูด Eclipsites มากมายที่นี่...",
  str_story_banner_527200404 = "ดังนั้น ภารกิจในการกำจัดขยะเหล่านี้จึงตกเป็นของคุณ!",
  str_story_banner_527200405 = "เขาแตกต่างจากยักษ์ใหญ่ของคุณ! เขาสามารถต่อสู้ได้เช่นกัน!",
  str_story_banner_527200406 = "รถแข่งคันนี้มีแกดเจ็ตและกับดักทุกรูปแบบที่ออกแบบมาเพื่อเปลี่ยนพวกสวะเหล่านั้นให้กลายเป็นเม็ดทราย!",
  str_story_banner_527200411 = "ฮ่าๆ! อีกไม่นานขยะเหล่านี้จะกลายเป็นฝุ่น! แค่คิดถึงก็ทำให้ฉันรู้สึกดีขึ้น",
  str_story_banner_527200412 = "หลังจากจัดการสิ่งโสโครกนี้แล้ว คู่รักที่มีเสน่ห์คนนี้ก็จะเหมือนฝน! คุณสามารถตั้งค่ากับดักได้มากเท่าที่คุณต้องการ!",
  str_story_banner_527200413 = "Bullock 8 สามารถกู้คืน Energy ได้ 1 แต้มทุกรอบ แน่นอนว่าการกำจัดขยะนี้ยังสามารถสะสมพลังงานให้กับเขาได้อีกด้วย",
  str_story_banner_527200414 = "แน่นอนว่าจะไม่มีกับดักมากเกินไป! ท้ายที่สุดแล้ว ทุกสิ่งมีขีดจำกัด และที่รักของฉันก็ไม่ใช่รถบรรทุกอิลลูมินาคันใหญ่ที่น่าเกลียด...",
  str_story_banner_527200415 = "โปรดทราบว่าเขาสามารถติดตั้งกับดักได้สูงสุด 6 ตัวเท่านั้น",
  str_story_banner_527200416 = "ถึงกระนั้น ฉันก็สามารถขอให้สุดที่รักของฉันปลดกับดักเหล่านั้นออกได้ และมันจะไม่เสียค่าใช้จ่ายใดๆ เลย!",
  str_story_banner_527200421 = "สไลม์บอลที่น่าขยะแขยงลูกนี้... มีบางอย่างที่แปลกไป... ดูเหมือนว่ามันจะไม่กลัวกับดักพวกนั้นเลย!",
  str_story_banner_527200422 = "และทักษะที่น่าขยะแขยงของมันสามารถทำลายกับดักได้! Caelestite ที่น่ารักของฉัน ระวังตัวด้วย!",
  str_story_banner_52740011 = "อย่างจริงจัง? ตอนนี้ฉันเป็นสมาชิกอาวุโส ทำไมฉันยังต้องจัดการกับสิ่งนี้?",
  str_story_banner_52740012 = "อยากกลับไปอ่านจริงๆ กำจัดความรำคาญเหล่านี้ให้เร็วที่สุดกันเถอะ",
  str_story_banner_52740013 = "แต่ละครั้งที่คุณแตะบนไทล์ที่ปรับปรุงแล้ว คุณสามารถเลือกจุดลงจอดอื่นได้",
  str_story_banner_52740014 = "ด้วยวิธีนี้ คุณสามารถดูดซับไทล์ที่ปรับปรุงแล้วด้วย Active Skill และเพิ่มความเสียหายขั้นสุดท้ายของทักษะอุปกรณ์ของคุณ เริ่มกันเลย!",
  str_story_banner_52740021 = "ฉันจะมอบภารกิจจัดส่งนี้ให้ดีที่สุด!",
  str_story_banner_52740022 = "จุ๊ๆ... เห็นสุริยุปราคารอบๆ ตัวเราไหม? กำจัดพวกมันก่อนที่เราจะออกสู่ท้องถนน เพื่อความปลอดภัย",
  str_story_banner_52740023 = "ได้เลย!",
  str_story_banner_52740024 = "เข้าใกล้พวกมันด้วยทักษะเทเลพอร์ต แล้วข้าจะจัดการการโจมตีเอง!",
  str_story_banner_52840011 = "PlayerNameฉันขอโทษจริงๆที่ต้องขอให้คุณช่วยฉันจัดการกับเรื่องนี้",
  str_story_banner_52840012 = "เป็นเพราะ...นอนแค่...12ชม....",
  str_story_banner_52840013 = "Zzzzzzz...",
