  str_story_banner_52840015 = "วิธีการเลือก Active Skill ของ Tina นั้นแตกต่างจาก Aurorians คนอื่นๆ ก่อนอื่นคุณต้องกำหนดเส้นทางการเคลื่อนไหวของเธอโดยการเชื่อมต่อกระเบื้อง",
  str_story_banner_52840016 = "หลังจากกำหนดเส้นทางของเธอแล้ว Tina จะเดินละเมอไปตามเส้นทางที่เลือก เปลี่ยนสีของกระเบื้องตามเส้นทางของเธอ และท้ายที่สุดจะกลับไปที่จุดเริ่มต้นของเธอ",
  str_story_banner_52840017 = "เมื่อเชื่อมต่อชิ้นส่วน คุณยังสามารถเชื่อมต่อชิ้นส่วนของศัตรูเป็นจุดสิ้นสุดของ Tina โดยไม่ต้องใช้จำนวนชิ้นส่วนที่คุณสามารถเชื่อมต่อได้",
  str_story_banner_52840018 = "ในสถานการณ์นี้ Tina จะหยุดบนกระเบื้องก่อนถึงจุดสิ้นสุดและสร้างความเสียหายให้กับศัตรู",
  str_story_banner_52840019 = "สุริยุปราคา! คุณกล้าดียังไงมาโชว์หน้าบูดของคุณใน Lumopolis! นี่เป็นสิ่งที่ยกโทษให้ไม่ได้!",
  str_story_banner_52840020 = "ขั้นแรกให้เพิ่มความเร็วอาวุธให้สูงสุด แล้วจึงเปิดใช้ทักษะ!",
  str_story_banner_52840021 = "กำลังเสริม? ดูเหมือนว่าเราจะต้องใช้ทักษะที่แท้จริงบางอย่างที่นี่",
  str_story_banner_52840022 = "ใช้ Active Skill! ปลดปล่อย Zeal ให้หมดและกวาดล้างพวกมันให้หมด!",
  str_story_banner_52840023 = "Eclipsites สกปรกเหล่านี้กล้าดีอย่างไรที่ทำให้ Lumopolis เป็นมลทิน! เราต้องชำระล้างพวกมัน!",
  str_story_banner_52840024 = "สามัญชน ฉันจะทิ้ง Eclipsites ที่อ่อนแอเหล่านั้นไว้ในมือคุณ",
  str_story_banner_52840025 = "ฉันจะทำความสะอาดส่วนที่เหลือ",
  str_story_banner_52840026 = "ฉันรวบรวมกำลังได้เพียงพอแล้ว ตอนนี้ถึงคราวที่ฉันต้องต่อสู้",
  str_story_banner_5299001 = "ฉัน-มันรถพังอีกแล้ว! คุณจำได้ไหมว่าเราแยกมันออกจากกันครั้งสุดท้ายอย่างไร?",
  str_story_banner_5299002 = "ขั้นแรก ตีเลื่อยลูกโซ่ Rick ที่ขวางทาง!",
  str_story_banner_5299003 = "<color=#FFB400>แตะที่ตัวศัตรูออโรเรียนก็จะเห็นว่าเขาจะทำอะไรถัดไป</color>",
  str_story_banner_5299004 = "<color=#FFB400>ออโรเรียนมักจะเล็งโจมตียูนิตศัตรูที่อยู่ใกล้สุดเสมอ</color>",
  str_story_banner_5299005 = "แต่พวกเขา <color=#FFB400>สามารถย้ายบนกระเบื้องขององค์ประกอบของตัวเองเท่านั้น!</color>\nรักษาระยะห่างของคุณและพยายามอย่างดีที่สุดที่จะไม่ปล่อยให้พวกเขาทำร้ายเรา",
  str_story_banner_5299006 = "Th-นี่แสดงค่า ATK และ HP ของศัตรู\nและฉันจะบอกว่ามันเป็นวิธีที่ค่อนข้างง่ายในการประเมินว่าคุณพร้อมรับความท้าทายหรือไม่",
  str_story_banner_5299007 = "มาเริ่มกันเลย!",
  str_story_banner_5299008 = "ยอดเลย!",
  str_story_banner_5299009 = "เอาล่ะ ฉันกับดาร์ควาสป์ตัวนั้นกำลังรอคำสั่งของคุณทั้งคู่\n(ฉัน-ถ้าเพียงแต่ฉันสามารถปล่อยให้ Darkwasp พุ่งไปข้างหน้าและหาที่ซ่อนได้...)",
  str_story_banner_5299010 = "โอ-ใช่! Lord Augean ได้พัฒนาความสามารถใหม่ให้สมบูรณ์แบบ! <color=#FFB400>เมื่อได้รับความเสียหายระยะประชิด ตอนนี้เขาสามารถโต้กลับผู้โจมตีได้แล้ว</color>!\nอย่าลืมใช้ทักษะพิเศษนี้ให้เกิดประโยชน์สูงสุด!",
  str_story_banner_5299011 = "อ-โอ้ ไม่นะ!\nฉันเพิ่งได้ยินว่าเพื่อนของเราที่ซุ่มอยู่ในลูโมโปลิสถูกค้นพบและกำลังต่อสู้กับผู้คุม!\nเราต้องรีบไปช่วยพวกเขาแล้ว!",
  str_story_banner_5299012 = "พวกมันอยู่ค่อนข้างไกล ดังนั้นลองใช้ <color=#FFB400>รูหนอน</color> ไปข้างหน้าเพื่อไปที่นั่นเร็วขึ้น",
  str_story_banner_5299013 = "แต่ก็ยังมีชาวออโรเรียนจำนวนมากขวางทาง...\nไม่ว่าคุณต้องการหลีกเลี่ยงหรือไม่นั้นขึ้นอยู่กับคุณ",
  str_story_banner_5299014 = "บาร์บาร่า!\nฉันได้ยินว่าเธอทำได้ <color=#FFB400>โจมตีและทำให้เรามึนงง</color>... เธอน่ากลัวชะมัด!",
  str_story_banner_5299015 = "B-แต่เรามีพันธมิตรที่แข็งแกร่งที่จะช่วยเหลือเรา—ธัมเปอร์!\nทัมเปอร์ก็ได้ <color=#FFB400>กระแทกเป้าหมายกลับ 2 แผ่น</color>!",
  str_story_banner_5299016 = "วิธีนี้ไม่เพียงแต่ใช้ได้กับชาว Aurorian เท่านั้น คุณยังสามารถใช้กับพันธมิตร Eclipsite ของคุณได้อีกด้วย!\nบางครั้งมันอาจทำให้คุณประหลาดใจเชิงกลยุทธ์ ...",
  str_story_banner_5299017 = "ลองดูสิ!",
  str_story_banner_5299018 = "ดูเหมือนว่าสถานการณ์จะคล้ายกับครั้งก่อน แต่ไม่มีความเสียหายจากกับดัก",
  str_story_banner_5299019 = "Y-คุณควรเริ่มคิดว่าคุณจะจัดการกับ Barbara อย่างไร...",
  str_story_banner_5299020 = "<color=#FFB400>บางที Thumper สามารถผลักดันเราไปข้างหน้า?</color>",
  str_story_banner_5299021 = "ในที่สุดเราก็มาถึง LL-Lumopolis!\nมากำจัด Lumo Guards เหล่านี้พร้อมกับพันธมิตร Eclipsite ของเรากันเถอะ!",
  str_story_banner_5299022 = "<color=#FFB400>Aphonic Assistant สามารถฟื้นฟู HP ให้กับพันธมิตร Eclipsite ของเราที่อยู่ในระยะ</color>, ให้การสนับสนุนที่สำคัญ!",
  str_story_banner_5299023 = "II-เขาเอง! ชายผู้ซ่อนตัวอยู่ในส่วนลึกที่สุดของ Lumopolis\n—<color=#FFB400>ชวาร์ตษ์!</color>",
  str_story_banner_5299024 = "ฉันกลัว ข-แต่เราถอยไม่ได้...",
  str_story_banner_5299025 = "P-ได้โปรด j-ยอมจำนน! ... ฉันฟังดูเหมือนฉันหมายถึงธุรกิจหรือไม่?",
  str_story_banner_5299026 = "อย่างไรก็ตาม ขอฝากเรื่องนี้ไว้กับลอร์ด Augean สำหรับฉัน...\nฉันจะเชียร์ทุกคนจากด้านหลัง! คุณ... คุณทำได้!",
  str_story_banner_52940011 = "แดรตส์... ฉันเจ็บ",
