  str_story_banner_52940013 = "ดูเหมือนว่าพวกเขาใช้ความพยายามอย่างมากในการสร้างสิ่งกีดขวางเหล่านั้น",
  str_story_banner_52940014 = "แต่พวกเขาก็ไร้เดียงสาเกินไป ถ้าพวกเขาคิดจะหยุดฉัน",
  str_story_banner_52940021 = "ระวังมี Eclipsites อยู่ข้างหน้า",
  str_story_banner_52940022 = "กระเบื้องแนวทแยงด้านหน้าเป็นสถานที่ที่ดีกว่าในการโจมตี มันจะดีมากถ้าฉันสามารถย้ายไปที่นั่นได้",
  str_story_banner_52940023 = "ไม่ต้องกังวล ฉันสามารถใช้ Active Skill Variant เพื่อย้ายเราไปที่นั่นได้",
  str_story_banner_52940024 = "Active Skill Variants คือรูปแบบของ Active Skills ที่มีเอฟเฟกต์แตกต่างกันเล็กน้อย การร่ายจะส่งผลต่อจำนวนคูลดาวน์ของ Active Skill ถัดไป",
  str_story_banner_52940025 = "ให้เพลงของฉันชำระล้างความชั่วร้ายทั้งหมด!",
  str_story_banner_11900701 = "คุณสามารถปรับแต่งอุปกรณ์ได้ที่นี่ ลองมาดูบางสิ่งที่คุณสามารถทำได้!",
  str_story_banner_11900801 = "คุณสามารถปรับแต่งอุปกรณ์ได้ที่นี่ ลองมาดูบางสิ่งที่คุณสามารถทำได้!",
  str_story_banner_29052011 = "คุณรู้สึกถึงความตายที่จะมาหาคุณไหม?\nรู้สึกว่าความตายเป็นอย่างไรสำหรับตัวคุณเอง",
