  str_story_banner_53940212 = "ลืมเรื่องนั้นไปก่อนสาวน้อย เรามาแก้ปัญหาที่เรากำลังเผชิญหน้ากันก่อนดีกว่า",
  str_story_banner_53940213 = "เกมหมากรุกเริ่มแล้ว",
