  str_story_banner_8024002 = "เอาล่ะ ถ้าเป็นอย่างนั้น ขอให้ฉันลองใช้วิธีการต่อสู้ที่แตกต่างไปดูบ้าง",
  str_story_banner_8024003 = "ถัดไป ขอฉันลองดูหน่อย",
  str_story_banner_8024004 = "ศัตรูใหม่ๆ ปรากฏขึ้นมาแล้ว ให้ฉันจัดการพวกมันเถอะ",
  str_story_banner_8024005 = "ฉันสามารถรู้สึกถึงพลังงานของ Formation Node ได้แล้ว มาลองกำจัดศัตรูทั้งหมดกันเถอะ",
  str_story_banner_5414011 = "เฮ้ PlayerName ตั้งแต่ฉันตื่นขึ้นมา ฉันได้พบสิ่งดี ๆ มากมายในโลกนี้ คุณจะร่วมกับฉันไปตรวจสอบสิ่งเหล่านั้นในวันนี้ไหม?",
  str_story_banner_5414012 = "แต่ในฐานะหญิงสาวมังกร ฉันต้องจัดการกับปัญหาใกล้เคียงก่อน",
  str_story_banner_5414013 = "โอกาสที่ฉันจะได้แสดงความสามารถของฉันนั้นไม่มาก ดังนั้นคุณควรจะเห็นคุณค่าในมัน",
  str_story_banner_5414014 = "เอาล่ะ ดูฉันจัดการกับความยุ่งยากนี้สิ!",
  str_story_banner_5414031 = "เมื่อเทศกาลฤดูใบไม้ผลิเข้ามาใกล้ วิญญาณร้ายกลับมาก่อกวนอีกครั้ง",
  str_story_banner_5414032 = "ศัตรูรวมตัวอยู่ที่มุม และวิธีการทั่วไปดูเหมือนจะไม่สามารถกำจัดพวกเขาทั้งหมดในครั้งเดียว นี่คือเวลาที่ดีที่สุดในการใช้สกิลที่มีอยู่ของฉัน: ระเบิดซุปรายส์! มาเถอะ อาดิง มาทำเครื่องหมายตำแหน่งของศัตรูและกำจัดพวกเขาด้วยดาเมจที่กระจาย!",
  str_story_banner_5414033 = "โอ้ ฉันลืมบอกคุณ ระเบิดแสนประหลาดของฉันมีหลายรูปแบบ คุณสามารถเลือกใช้สกิลรูปแบบหนึ่งจากหลายรูปแบบ แต่ละรูปแบบมีระยะเวลาคูลดาวน์ที่แตกต่างกันหลังจากร่ายสกิล",
  str_story_banner_5414034 = "Surprise Grenade Variant I เพิ่มพลังการโจมตีปกติ ในขณะที่ Surprise Grenade Variant II ให้ผลกระทบการผลักถอยหลังให้กับ Chain Combos หลังจากที่ถูกร่าย โปรดเลือกสกิลเวอร์ชันที่แตกต่างกันอย่างฉลาดตามสถานการณ์เพื่อเพิ่มพลังการทำความเสียหายของคุณให้เต็มที่!",
  str_story_banner_54193101 = "พวกเขาบอกว่าฉันบ้าไปแล้ว... คุณบ้าเหมือนฉันเหรอ? แบบที่ฉันบ้านั้นเหรอ?",
  str_story_banner_54193102 = "บ้าเหรอ ฮีฮี... ฮ่าฮ่าฮ่า! เรียกฉันว่าคนบ้าถ้าคุณต้องการ.",
  str_story_banner_54193103 = "เคลย์มอร์ คุณ... คุณกำลังพยายามซ่อนตัวจริงของคุณใต้ชื่อนั้นหรือ? อคิลลิส บอกฉันสิ มันเกิดอะไรขึ้น?!",
  str_story_banner_54193104 = "ฉันต้องพาคุณลงไป...",
  str_story_banner_54193105 = "นี่คือสิ่งที่กำลังเกิดขึ้นที่นี่!",
