  str_story_banner_54193107 = "อคิลลีส",
  str_story_banner_16022511 = "ฮืม! คิดว่าจะจับฉันได้แค่ด้วยการทำงานร่วมกันเหรอ?",
  str_story_banner_16022512 = "ไม่ต้องห่วงนะ สำหรับนักล่าที่ยอดเยี่ยมเช่นฉัน หาจุดอ่อนของเหยื่อเป็นเรื่องง่าย!",
  str_story_banner_16022513 = "ในระหว่างการล่า เหยื่อมักจะแสดงจุดอ่อนออกมามากมาย กฎแรกของการล่าคือการค้นหาและนำเอาจุดอ่อนเหล่านี้มาใช้ประโยชน์!",
  str_story_banner_16022514 = "เมื่อฉันจับจุดอ่อนของพวกมันได้ สัตว์รับนี้จะไม่มีโอกาสต่อหอกของฉันหรอก!",
  str_story_banner_900107011 = "ความเห็น: ความทรงจำและอารมณ์ที่ถูกทิ้งไว้โดยผู้ฝันเริ่มแรกถูกหุ้มด้วยพลังงานความฝันทีละชั้น สร้างเป็น Dream Orbs",
  str_story_banner_900107012 = "ในฐานะผู้กระจ่างให้สว่างของคุณ ฉันต้องเตือนคุณว่าในระหว่างการสำรวจ คุณจะมีโอกาสได้รับ Dream Orbs ที่กระจายอยู่ทั่วทั่วฝัน",
  str_story_banner_900107013 = "โดยการวาง Dream Orbs ลงใน Enlightenment Spiral คุณสามารถวิเคราะห์ความทรงจำการต่อสู้ภายใน Dream Orbs ปลดล็อกสกิลที่เกี่ยวข้องเพื่อช่วยออโรเรียนในการต่อสู้",
  str_story_banner_900108011 = "คำแนะนำ: ผู้กระจ่างให้สว่างจะเปลี่ยนเป็นโหมด Enlightenment Cube ทำให้สามารถร่วมสู้กับออโรเรียนได้",
  str_story_banner_900108012 = "ในการต่อสู้, ผู้กระจ่างให้สว่างจะได้รับพลังงาน 1 แต้มสำหรับทุกช่องที่ออโรเรียนเดินทาง",
  str_story_banner_900108013 = "หลังจากออโรเรียนเชื่อมต่อไทล์และปล่อยคอมโบต่อเนื่องทั้งหมด ถ้าผู้กระจ่างให้สว่างสะสมพลังงานมากกว่าที่จำเป็นสำหรับ Dream Orbs คุณสามารถปล่อยสกิลของ Dream Orbs บน Enlightenment Spiral ได้",
  str_story_banner_900108014 = "คุณสามารถลองเชื่อมต่อชิ้นส่วนได้หนึ่งครั้งตอนนี้",
  str_story_banner_900108021 = "ข่าวดี: คุณได้รับพลังงานแล้ว คุณสามารถดูสถานะการชาร์จและรายละเอียดการประกอบของ Dream Orbs ที่นี่",
  str_story_banner_900108031 = "ความเห็น: มี Dream Orbs หลากหลายประเภท ซึ่ง Charging Orbs สามารถช่วยคุณได้รับพลังงานเพิ่มเติมและเร่งความคืบหน้าในการชาร์จ",
  str_story_banner_900108032 = "ในขณะเดียวกัน ลูกแก้วการเสริมสร้างสามารถเพิ่มความแข็งแกร่งของลูกแก้วสกิลบนสปิราลการรู้สึก",
  str_story_banner_900108033 = "การรวมกันอย่างฉลาดสามารถปลดปล่อยศักยภาพเต็มรูปแบบของ Dream Orbs ให้ได้ ในฐานะผู้กระจ่างให้สว่างของคุณ ฉันเชื่อว่าคุณจะพบความสุขในสิ่งนี้แน่นอน",
  str_story_banner_5416011 = "อิคลิพไซท์ปรากฏขึ้นข้างหน้า? ดูเหมือนว่าจะเป็นงานของกลุ่มนักล่าอินทรี",
  str_story_banner_5416012 = "ยืนยันตำแหน่งของคุณและใช้ Death Recon เพื่อสอดแนมหาเส้นทางเข้าสู่ภายใน",
  str_story_banner_5416013 = "รายงาน! นักล่าอินทรีศูนย์ได้บุกเข้าสู่เขตของศัตรู; ถึงเวลาเริ่มการโจมตีแล้ว! ขอร้องให้โดรนทั้งหมดโจมตีศัตรู!",
  str_story_banner_5416014 = "ลองใช้ Death Recon อีกครั้งสิ! มันจะทำให้ฉันอยู่ในสถานะ Exhausted และป้องกันไม่ให้ฉันใช้การโจมตีปกติหรือคอมโบชุด... แต่ Eagle Hunters จะล็อคเป้าหมายศัตรูและกำจัดพวกมันแทนฉัน!",
  str_story_banner_5416021 = "ข่าวดี เคเลสไทต์คนสุดท้าย! วันนี้ คุณมีสิทธิพิเศษที่จะได้ร่วมสู้ด้วยกับเซต้า ฮีโร่ตำนานผู้กอบกู้ทั้งหมดแอสตรา!",
  str_story_banner_5416022 = "คุณได้พบกับสมาชิกคณะอื่น ๆ ของฉันแล้วใช่ไหม? ฉันกำลังพูดถึงหุ่นยนต์น่ารักที่ระเบิดเรื่องนี้ - โคนันผู้รู้เท่าทัน!",
  str_story_banner_5416023 = "โคแนนผู้รู้เท่าทันไม่ยอมใครเลยนอกจากฉัน! ดูเท่ห์ไหมล่ะ?",
  str_story_banner_5416024 = "คุณควรจำสิ่งนี้ไว้ดีๆ เคเลสไทต์คนสุดท้าย: เมื่อแผงสีถูกปกคลุมด้วยสีทั้งสี่ คุณสามารถเรียกคอนันผู้รู้ทั้งหมดมาใหม่! ฉันไม่ได้แบ่งปันทักษะลับนี้กับทุกคน ดังนั้นเก็บมันเป็นความลับนะ?",
  str_story_banner_5466011 = "ฉันกำลังจะตั้งสถิติใหม่สำหรับ Tetrablox! แต่มีอิคลิพไซท์... ไม่มีทางหลีเลี่ยง ฉันจะต้องกำจัดคุณเพื่อได้คะแนนเพิ่ม!",
  str_story_banner_5466012 = "ขั้นแรก, รับคิวถัดไป!",
  str_story_banner_5466013 = "บล็อกที่คุณเห็นอยู่ตรงกลางจอแสดงผลคือระยะการเปลี่ยนสีช่องของ Active Skill ในขณะนี้",
